; CYCLES_FORWARD_BRANCHES
; AERIA PT2399 -- Chloaelis' PT2399 delay (DSP.h PT2399Line in DelayCell) in 24-bit fixed point. Generated by pt2399/gen.py.
; Dual mono, hard panned. Per side: s = x + fb -> input lowpass (bw) -> CVSD encoder at the chip clock (<= 3 bits a
; sample; under 333 ms the read tap shortens instead) -> 44040 bits of RAM -> decoder at the read head -> the
; sample's mean held -> output lowpasses (bw, 1.25 bw) -> DC block -> + noise + clock whine -> wet rider (0.95 FS)
; -> fb = 1.05 regen hpf(wet). bw = clamp(0.048 clock, 2.4 k, 11.5 k) x TONE. No tanh anywhere (see gen.py).
;  knob 0 TIME  50 ms x 20^(v/127)    knob 1 SKEW  right time x 2^((v-64)/64)
;  knob 2 FDBK  regen 1.15 v/127 (x 1.05)  knob 3 TONE  bw x 2^((v-100)/24)
;  knob 4 GRIT  dMax x 2^-((v-64)/32) (127: overloads sooner)   knob 5 MIX
;  FUNC r6+$c: HPF (22..16) FRZ (14..8); r6+$d: RFRZ (the ColdFire's) TMOD (14..8: 0 SLEW, 1 FADE);
;  r6+$e: MOD (22..16, LFO>Time depth) RATE (14..8, 0.02 .. 20 Hz). r6+6: the ColdFire's freeze word (bit 0 L, bit 1 R).
; RAM in X: 1835 words a side (left at the base, right at base + $800; masks at base + $740); the base a multiple of
; $1000: the word X:$213 points to, used as an X address (core 1 X:$8000)
; common r7: 00 CLR 01 FIRST 02 MIXT 03 MIXC 04 KFBT 05 TONS 06 GRIT 07 TJOB 08 RNG 09 RND 0a FRZM 0b TMOD 0c MODK 0d RATK 0e SIDE 0f R6S 10 MSKB 11 SC0 12 SC1 13 SC2 14 SC3 15 SC4 16 SC5 17 INV0 18 INV1 19 INV2 1a INV3 1b INV4, HPF coefs $1c
; sides at r7+$30 / r7+$98 (r1 / r2 = 64 words in): 00 BN0 01 BN1 02 BN2 03 BN3 04 BN4 05 LN0 06 LN1 07 LN2 08 LN3 09 LN4 0a NK0 0b NK1 0c NK2 0d NK3 0e NK4 0f RK0 10 RK1 11 RK2 12 RK3 13 RK4 14 CW 15 PHW 16 CA 17 PHA 18 IW 19 MW 1a IA 1b MA 1c XI 1d PREVIN 1e WIN 1f EE 20 SS 21 HH 22 ED 23 SD 24 HD 25 SUM 26 HELD 27 CEQ 28 TGT 29 NCUR 2a NCL 2b LFO 2c CENV 2d DCX 2e DCH 2f DCL 30 RENV 31 FB8 32 WET 33 GA 34 DGA 35 GART 36 DGG 37 GEND 38 KNO 39 KWH 3a WPH 3b WINC 3c FROZ 3d KFB 3e MODE 3f PCNT 40 CNEW 41 WAIT 42 H 43 XENV coefs {'IN': 68, 'O1': 73, 'O2': 78} hist {'IN': 83, 'OUT': 87, 'HP': 93}
init:
        move    #>$ffffff,m4
        move    r7,r4
        clr     a
        do      #$100,>ptzero
        move    a,x:(r4)+
ptzero:
        nop     
        move    x:>$213,r4
        nop     
        move    x:(r4),a
        move    a,b
        add     #>$000740,b
        move    b,x:(r7+$10)
        move    r7,b
        add     #>$000070,b
        move    b1,r4
        move    a,x:(r4-$28)
        move    a,x:(r4-$26)
        move    x:(r7+$10),x0
        move    x0,x:(r4-$27)
        move    x0,x:(r4-$25)
        add     #>$800,a
        move    r7,b
        add     #>$0000d8,b
        move    b1,r4
        move    a,x:(r4-$28)
        move    a,x:(r4-$26)
        move    x:(r7+$10),x0
        move    x0,x:(r4-$27)
        move    x0,x:(r4-$25)
        add     #>$800,a
        move    #>$000000,a
        move    a,x:(r7+$17)
        move    #>$7fffff,a
        move    a,x:(r7+$18)
        move    #>$400000,a
        move    a,x:(r7+$19)
        move    #>$2aaaab,a
        move    a,x:(r7+$1a)
        move    #>$200000,a
        move    a,x:(r7+$1b)
        move    #>$8,a
        move    a,x:(r7+$00)
        move    #>$1,a
        move    a,x:(r7+$01)
        move    #>$12345,a
        move    a,x:(r7+$08)
        rts     
proc:
        move    #>$ffffff,m1
        move    #>$ffffff,m2
        move    #>$ffffff,m4
        move    #>$ffffff,m5
        move    #>$ffffff,m3
        move    r7,a
        add     #>$000070,a
        move    a1,r1
        move    r7,a
        add     #>$0000d8,a
        move    a1,r2
; bounded clearing: 8 dry calls, 256 words of each side's 2,048 a call; then the 24 masks
        move    x:(r7+$00),a
        tst     a
        beq     ptready
        sub     #>$1,a
        move    a,x:(r7+$00)
        asl     #$8,a,a
        move    a1,x0
        move    x:(r1-$28),a
        add     x0,a
        move    a1,r4
        move    #>$aaaaaa,a  ; the idle pattern: stream bit p = p & 1, and p & 1 = (p mod 24) & 1
        do      #256,>ptcz001
        move    a,x:(r4)+
ptcz001:
        nop     
        move    x:(r2-$28),a
        add     x0,a
        move    a1,r4
        move    #>$aaaaaa,a  ; the idle pattern: stream bit p = p & 1, and p & 1 = (p mod 24) & 1
        do      #256,>ptcz002
        move    a,x:(r4)+
ptcz002:
        nop     
        move    x:(r7+$00),a
        tst     a
        bne     ptcm003
        move    x:(r7+$10),r4
        move    #>$1,a
        do      #24,>ptmsk
        move    a1,x:(r4)+
        lsl     a
ptmsk:
        nop     
ptcm003:
        rts     
ptready:
        move    x:(r6+$5),a
        move    #>$7f0000,x0
        cmp     x0,a
        blt     ptmt004
        move    #>$7fffff,a
ptmt004:
        move    a,x:(r7+$02)
        move    x:(r7+$03),b
        sub     b,a
        abs     a
        cmp     #>$000100,a
        bge     ptms005
        move    x:(r7+$02),a
        move    a,x:(r7+$03)
ptms005:
        move    x:(r6+$2),x0
        move    #>$4de375,y0
        mpy     y0,x0,a
        move    a,x:(r7+$04)
; GRIT/4 = 2^-(v/32) (dMax x 4 .. x 1/4)
        move    x:(r6+$4),x0
        move    #>$100000,y0
        mpy     y0,x0,a
        bsr     >ptexp
        move    b,x:(r7+$06)
        move    x:(r6+$3),a
        move    x:(r7+$05),b
        sub     b,a
        asr     #$3,a,a
        add     a,b
        move    x:(r7+$01),a
        tst     a
        beq     pttf006
        move    x:(r6+$3),b
pttf006:
        move    b,x:(r7+$05)
        move    x:(r6+$c),a
        and     #>$7f0000,a
        move    a1,a
        tst     a
        beq     pthp007
        move    #>$3da04c,a
        move    a,x:(r7+$1c)
        move    #>$84bf68,a
        move    a,x:(r7+$1d)
        move    #>$3da04c,a
        move    a,x:(r7+$1e)
        move    #>$84cfcf,a
        move    a,x:(r7+$1f)
        move    #>$3b50ff,a
        move    a,x:(r7+$20)
        bra     pthq008
pthp007:
        move    #>$400000,a
        move    a,x:(r7+$1c)
        move    #>$000000,a
        move    a,x:(r7+$1d)
        move    #>$000000,a
        move    a,x:(r7+$1e)
        move    #>$000000,a
        move    a,x:(r7+$1f)
        move    #>$000000,a
        move    a,x:(r7+$20)
pthq008:
        move    x:(r6+$c),a
        lsl     #8,a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0a)
        move    x:(r6+$d),a
        lsl     #8,a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0b)
        move    x:(r6+$e),a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0c)
        move    x:(r6+$e),a
        lsl     #8,a
        and     #>$7f0000,a
        move    a1,a
        move    a,x:(r7+$0d)
        move    r1,r3
        move    #>$1,a
        move    a,x:(r7+$0e)
        bsr     >ptside
        move    r2,r3
        move    #>$2,a
        move    a,x:(r7+$0e)
        bsr     >ptside
        bsr     >pttone
        move    #>$0,a
        move    a,x:(r7+$01)
        move    r6,x:(r7+$0f)
        move    r1,n1
        move    r2,n2
        move    #>$00072a,m4
        move    #>$17,m5
        do      n7,>ptloop
        move    x:(r7+$02),a
        move    x:(r7+$03),b
        sub     b,a
        asr     #$7,a,a
        add     a,b
        move    b,x:(r7+$03)
        move    x:(r7+$08),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$08)
        move    a1,x:(r7+$09)
        move    n1,r1
        bsr     >ptsamp
        move    n2,r1
        bsr     >ptsamp
        nop     
ptloop:
        nop     
        move    #>$ffffff,m4
        move    #>$ffffff,m5
        move    x:(r7+$0f),r6
        move    n1,r1
        move    n2,r2
        move    x:(r1-$09),a
        move    a,x:(r1-$0b)
        move    x:(r2-$09),a
        move    a,x:(r2-$0b)
        rts     
ptsamp:
; ======== one side (r1 = its block, 64 words in); x:(r0) in, x:(r0)+ out ========
        move    x:(r0),a
        asr     #$3,a,a
        move    x:(r1-$0f),x0
        add     x0,a
        move    a,x0  ; s/8
        abs     a
        move    x:(r1-$14),x1
        move    #>$7fef7e,y0
        mpy     x1,y0,b
        max     a,b
        move    b,x:(r1-$14)
        move    x:(r0),a
        abs     a
        move    x:(r1+$03),x1
        move    #>$7fef7e,y0
        mpy     x1,y0,b
        max     a,b
        move    b,x:(r1+$03)
; input lowpass (bw, Q 0.62; the op-amp's 0.99 folded in)
        move    x:(r1+$04),y0
        mpy     y0,x0,a
        move    x:(r1+$13),y1
        move    x:(r1+$05),y0
        mac     y1,y0,a
        move    x:(r1+$14),x1
        move    x:(r1+$06),y0
        mac     x1,y0,a
        move    y1,x:(r1+$14)
        move    x0,x:(r1+$13)
        move    x:(r1+$15),y1
        move    x:(r1+$07),y0
        mac     -y1,y0,a
        move    x:(r1+$16),x1
        move    x:(r1+$08),y0
        mac     -x1,y0,a
        asl     a
        rnd     a
        move    a,x0
        move    y1,x:(r1+$16)
        move    x0,x:(r1+$15)
        move    x0,x:(r1-$22)
; ---- the decoder (head A): n <= 4 edges; HELD = the mean of its values over the sample
        move    x:(r1-$29),a
        move    x:(r1-$2a),x0
        add     x0,a
        move    a1,b
        asr     #$14,b,b
        move    b1,b
        and     #>$0fffff,a
        move    a1,x:(r1-$29)
        move    b1,n3
        move    b1,x0
        move    x:(r1-$01),a
        tst     a
        beq     ptdp011
        sub     x0,a  ; old-clock bits still to read
        move    a,x:(r1-$01)
        bgt     ptdp011
        move    x:(r1+$00),a
        move    a,x:(r1-$2a)
        move    #>$0,a
        move    a,x:(r1-$01)
ptdp011:
        tst     b
        beq     ptdd009
        lua     (r7+$17),r3
        move    x:(r3+n3),y0  ; 1/n
        move    x:(r1-$26),r4
        move    x:(r1-$25),r5
        move    x:(r1-$1d),y1
        move    x:(r1-$1e),b
        move    #>$0,r6
        clr     a
        move    a,x:(r1-$1b)
        do      n3,>ptde010
        move    x:(r5)+,x0
        move    x:(r4)+,a
        and     x0,a
        beq     ptdz012
        add     y1,b
        move    x:(r1-$1c),a
        asl     a
        add     #>$1,a
        bra     ptdn013
ptdz012:
        sub     y1,b
        move    x:(r1-$1c),a
        asl     a
ptdn013:
        move    a1,x:(r1-$1c)
        add     #>$1,a
        and     #>$6,a
        bne     ptnr014
        move    (r6)+
ptnr014:
        move    b,x0
        move    x:(r1-$1b),a
        mac     y0,x0,a
        move    a,x:(r1-$1b)
ptde010:
        move    r4,x:(r1-$26)
        move    r5,x:(r1-$25)
        move    b,x:(r1-$1e)
        move    x:(r1-$1b),a
        move    a,x:(r1-$1a)
        lua     (r1-$3b),r3
        move    x:(r3+n3),x0
        move    x:(r1-$1e),y0
        mpy     y0,x0,a
        move    a,x:(r1-$1e)
        lua     (r1-$40),r3
        move    x:(r3+n3),x0
        move    x:(r1-$1d),y0
        mpy     y0,x0,a
        lua     (r1-$36),r3
        move    x:(r3+n3),x0
        add     x0,a
        move    r6,n3
        lua     (r1-$31),r3
        move    x:(r3+n3),x0
        add     x0,a
        move    a,x:(r1-$1d)
ptdd009:
; ---- the encoder: n <= 3 edges; the input interpolated prev -> u across them; RAM bit p = word p mod 1835, mask p mod 24
        move    x:(r1-$2b),a
        move    x:(r1-$2c),x0
        add     x0,a
        move    a1,b
        asr     #$14,b,b
        move    b1,b
        and     #>$0fffff,a
        move    a1,x:(r1-$2b)
        move    b1,n3
        move    b1,x0
        move    x:(r1-$04),a
        tst     a
        bne     ptez017
        tst     b
        beq     pted015
        lua     (r7+$17),r3
        move    x:(r3+n3),y0  ; 1/n
        move    x:(r1-$22),b
        move    x:(r1-$23),x1
        sub     x1,b
        move    b,x0
        mpy     y0,x0,b
        move    b,x1  ; dx
        move    x:(r1-$23),a
        move    a,x:(r1-$24)
        move    x:(r1-$28),r4
        move    x:(r1-$27),r5
        move    x:(r1-$20),y1
        move    x:(r1-$21),b
        move    #>$0,r6
        do      n3,>ptee016
        move    x:(r1-$24),a
        add     x1,a
        move    a,x:(r1-$24)
        cmp     b,a  ; u - E
        move    x:(r5)+,x0  ; (moves keep the flags) this bit's mask
        move    x:(r4),a
        bgt     pte1018
        or      x0,a
        eor     x0,a
        move    a1,x:(r4)+  ; bit 0
        sub     y1,b  ; E -= S
        move    x:(r1-$1f),a
        asl     a
        bra     pten019
pte1018:
        or      x0,a
        move    a1,x:(r4)+  ; bit 1
        add     y1,b  ; E += S
        move    x:(r1-$1f),a
        asl     a
        add     #>$1,a
pten019:
        move    a1,x:(r1-$1f)
        add     #>$1,a
        and     #>$6,a
        bne     ptnr020
        move    (r6)+
ptnr020:
        nop     
ptee016:
        move    r4,x:(r1-$28)
        move    r5,x:(r1-$27)
        move    b,x:(r1-$21)
        lua     (r1-$3b),r3
        move    x:(r3+n3),x0
        move    x:(r1-$21),y0
        mpy     y0,x0,a
        move    a,x:(r1-$21)
        lua     (r1-$40),r3
        move    x:(r3+n3),x0
        move    x:(r1-$20),y0
        mpy     y0,x0,a
        lua     (r1-$36),r3
        move    x:(r3+n3),x0
        add     x0,a
        move    r6,n3
        lua     (r1-$31),r3
        move    x:(r3+n3),x0
        add     x0,a
        move    a,x:(r1-$20)
        bra     pted015
ptez017:
; frozen: nothing is written; the writer still moves with the clock
        move    x:(r1-$28),r4
        move    x:(r1-$27),r5
        move    n3,n4
        move    n3,n5
        lua     (r4)+n4,r4
        lua     (r5)+n5,r5
        move    r4,x:(r1-$28)
        move    r5,x:(r1-$27)
pted015:
        move    x:(r1-$22),x0
        move    x0,x:(r1-$23)
; ---- out: HELD x the dip gain -> output lowpasses -> DC block -> + noise + whine -> gate -> rider
        move    x:(r1-$1a),x0
        move    x:(r1-$0d),y0
        mpy     y0,x0,a
        move    a,x0
        move    x:(r1+$09),y0
        mpy     y0,x0,a
        move    x:(r1+$17),y1
        move    x:(r1+$0a),y0
        mac     y1,y0,a
        move    x:(r1+$18),x1
        move    x:(r1+$0b),y0
        mac     x1,y0,a
        move    y1,x:(r1+$18)
        move    x0,x:(r1+$17)
        move    x:(r1+$19),y1
        move    x:(r1+$0c),y0
        mac     -y1,y0,a
        move    x:(r1+$1a),x1
        move    x:(r1+$0d),y0
        mac     -x1,y0,a
        asl     a
        rnd     a
        move    a,x0
        move    x:(r1+$0e),y0
        mpy     y0,x0,a
        move    x:(r1+$19),y1
        move    x:(r1+$0f),y0
        mac     y1,y0,a
        move    x:(r1+$1a),x1
        move    x:(r1+$10),y0
        mac     x1,y0,a
        move    y1,x:(r1+$1a)
        move    x0,x:(r1+$19)
        move    x:(r1+$1b),y1
        move    x:(r1+$11),y0
        mac     -y1,y0,a
        move    x:(r1+$1c),x1
        move    x:(r1+$12),y0
        mac     -x1,y0,a
        asl     a
        rnd     a
        move    a,x0
        move    y1,x:(r1+$1c)
        move    x0,x:(r1+$1b)
        move    x0,a
        move    x:(r1-$13),y0
        sub     y0,a
        move    x0,x:(r1-$13)
        move    x:(r1-$12),b
        move    x:(r1-$11),b0
        add     b,a
        move    x:(r1-$12),x1
        move    #>$002eb0,y0
        mac     -x1,y0,a
        move    a1,x:(r1-$12)
        move    a0,x:(r1-$11)
        rnd     a
        move    x:(r7+$09),x0
        move    x:(r1-$08),y0
        mac     y0,x0,a  ; + noise
        move    a,x:(r1-$0e)
; clock whine: a triangle at the folded clock x 15.55
        move    x:(r1-$06),a
        move    x:(r1-$05),x0
        add     x0,a
        and     #>$7fffff,a
        move    a1,x:(r1-$06)
        move    a1,a
        sub     #>$400000,a
        abs     a
        sub     #>$200000,a
        move    a,x0  ; tri / 4
        move    x:(r1-$07),y0
        move    x:(r1-$0e),a
        mac     y0,x0,a
; gate (ramped)
        move    a,x0
        move    x:(r1-$0b),b
        move    b,y0
        mpy     y0,x0,a
        move    x:(r1-$0a),x1
        add     x1,b
        move    b,x:(r1-$0b)
; wet rider: g = min(1, C/env)
        move    a,x0
        abs     a
        move    x:(r1-$10),x1
        move    #>$7ff892,y0
        mpy     x1,y0,b
        max     a,b
        move    b,x:(r1-$10)
        move    #>$0f3333,x1
        cmp     x1,b
        ble     ptgn021
        move    b,y1
        move    x1,a
        andi    #$fe,ccr
        do      #13,>ptgv023
        div     y1,a
ptgv023:
        nop     
        move    a0,b
        asl     #$b,b,b
        move    b,y0
        mpy     y0,x0,a
        bra     ptgd022
ptgn021:
        move    x0,a
ptgd022:
        move    a,x0
        move    x0,x:(r1-$0e)
; feedback high-pass (identity when off); fb/8 = (kfb/2) hpf(wet/8) 2
        move    x:(r7+$1c),y0
        mpy     y0,x0,a
        move    x:(r1+$1d),y1
        move    x:(r7+$1d),y0
        mac     y1,y0,a
        move    x:(r1+$1e),x1
        move    x:(r7+$1e),y0
        mac     x1,y0,a
        move    y1,x:(r1+$1e)
        move    x0,x:(r1+$1d)
        move    x:(r1+$1f),y1
        move    x:(r7+$1f),y0
        mac     -y1,y0,a
        move    x:(r1+$20),x1
        move    x:(r7+$20),y0
        mac     -x1,y0,a
        asl     a
        rnd     a
        move    a,x0
        move    y1,x:(r1+$20)
        move    x0,x:(r1+$1f)
        move    x:(r1-$03),y0
        mpy     y0,x0,a
        asl     a
        move    a,x:(r1-$0f)
        move    x:(r1-$0d),a
        move    x:(r1-$0c),x0
        add     x0,a  ; (the block code stops the ramp a call early: it never leaves [0, 1])
        move    a,x:(r1-$0d)
; mix
        move    x:(r1-$0e),a
        asl     #$3,a,a
        move    x:(r7+$03),y1
        move    x:(r0),b
        sub     b,a
        asr     a
        move    a,x0
        mpy     x0,y1,a
        asl     a
        add     b,a
        move    a,x:(r0)+
        rts     
ptside:
