        move    b,x0
        mpy     x0,y1,b
        move    b,x:(r4+$4)
        move    x1,x0
        mpy     x0,y1,b
        move    b,x0
        move    x:(r7+$14),y0
        mpy     y0,x0,b
        move    b,x:(r4)
        move    b,x:(r4+$2)
        asl     b
        move    b,x:(r4+$1)
        rts     
ptclk:
; CEQ (/32) -> CW = min(CAP, CEQ) (/8); a = N = RAMB min(CAP, CEQ)/CEQ (bits / 65536)
        move    x:(r3-$19),a
        cmp     #>$0c0000,a
        bgt     ptck049
        asl     #$2,a,a
        move    a,x:(r3-$2c)
        move    #>$560400,a
        bra     ptcd050
ptck049:
        move    #>$300000,b
        move    b,x:(r3-$2c)
        move    a,x0
        move    #>$0c0000,a
        bsr     >ptdiv  ; CAP/CEQ
        move    b,x0
        move    #>$560400,y0
        mpy     y0,x0,a
ptcd050:
        rts     
ptseek:
; a = N (bits / 65536): head A := the writer's place - N; NCUR = N. word = (IW - N) mod 1835, mask = (MW - N) mod 24
        move    a,x:(r3-$17)
        move    #>$0,x0
        move    x0,x:(r3-$16)
        move    x:(r3-$2b),x0  ; the head ticks with the writer: a whole number of bits apart, never past a lap
        move    x0,x:(r3-$29)
        move    a,x0
        bsr     >ptbits
        move    a1,x:(r7+$14)  ; N bits
        move    x:(r7+$14),x0
        move    #>$0011db,y0
        mpy     y0,x0,a  ; floor(N/1835) (maybe one short)
        move    a1,x1
        move    #>$00072b,y0
        move    x1,a
        move    #>$0,b
; r = N - 1835 q (q x 1835 by repeated adds is too long: multiply as integers via the fraction product)
        move    #>$00072b,y0
        mpy     x1,y0,a
        asr     a
        move    a0,x0  ; 1835 q
        move    x:(r7+$14),a
        sub     x0,a  ; r
        move    #>$00072b,x0
        cmp     x0,a
        blt     ptmr051
        sub     x0,a
ptmr051:
        move    a1,y1  ; N mod 1835
        move    x:(r3-$28),a
        and     #>$fff800,a
        move    a1,x:(r7+$13)  ; the ring base
        move    x:(r3-$28),a
        and     #>$0007ff,a
        sub     y1,a
        bge     ptmp052
        add     #>$00072b,a
ptmp052:
        move    x:(r7+$13),x0
        add     x0,a
        move    a1,x:(r3-$26)
        move    x:(r7+$14),x0
        move    #>$055555,y0
        mpy     y0,x0,a  ; floor(N/24) (maybe one short)
        move    a1,x1
        move    #>$000018,y0
        move    x1,a
        move    #>$0,b
; r = N - 24 q (q x 24 by repeated adds is too long: multiply as integers via the fraction product)
        move    #>$000018,y0
        mpy     x1,y0,a
        asr     a
        move    a0,x0  ; 24 q
        move    x:(r7+$14),a
        sub     x0,a  ; r
        move    #>$000018,x0
        cmp     x0,a
        blt     ptmr053
        sub     x0,a
ptmr053:
        move    a1,y1  ; N mod 24
        move    x:(r7+$10),a
        move    a1,x:(r7+$13)
        move    x:(r3-$27),a
        move    x:(r7+$10),x0
        sub     x0,a
        sub     y1,a
        bge     ptmp054
        add     #>$000018,a
ptmp054:
        move    x:(r7+$13),x0
        add     x0,a
        move    a1,x:(r3-$25)
        rts     
ptbits:
; x0 = N (bits / 65536) -> a1 = N in whole bits (rounded)
        move    x0,a
        add     #>$40,a
        asr     #$7,a,a
        move    a1,a
        rts     
ptdiv:
; a1 / x0 (0 <= a1 < x0) -> b (Q23)
        move    a1,a
        andi    #$fe,ccr
        do      #24,>ptdvend
        div     x0,a
ptdvend:
        nop     
        move    a0,b
        rts     
ptexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>ptxpend
        asr     b
ptxpend:
        asl     b
        rts     
